code_example:
#include <iostream>
class Base {
public:
  virtual void draw() { std::cout << "Base::draw()\n"; }
  virtual void rotate(int angle) = 0; //pure virtual function
};
class Derived : public Base {
public:
  void rotate(int angle) override { std::cout << "Derived::rotate(" << angle << ")\n"; }
  void draw() override { std::cout << "Derived::draw()\n"; } // explicitly overriding draw()
};
class Derived2 : public Base {
public:
  void rotate(int angle) override { std::cout << "Derived2::rotate(" << angle << ")\n"; }
};
int main() {
  Base* b = new Derived();
  b->draw();
  b->rotate(90);
  Base* b2 = new Derived2();
  b2->draw();
  b2->rotate(180);
  return 0;
}
